CH = dict(num=20, tag="Economics · Ch 4", theme="MNCs, foreign trade, liberalisation, WTO and the impact of globalisation",
 title="Globalisation and the Indian Economy",
 intro="Globalisation is the rapid integration of countries through foreign trade and foreign investment. This chapter explains the role of multinational companies, the factors that enabled globalisation, India's policy shift in 1991, the role of the WTO, the impact on producers and workers and the call for fair globalisation.",
 big_questions=["What is production across countries?", "What drives globalisation?", "What happened in India after 1991?", "Who gains and who loses?", "How can globalisation be made fair?"],
 blocks=[
 ("h2", "Production Across Countries"),
 ("note", "DEFINITION", "A **multinational corporation (MNC)** is a company that owns or controls production in more than one nation. MNCs set up offices and factories for production in regions where they can get cheap labour and other resources, which reduces their cost of production and raises profits."),
 ("ul", ["Earlier, production was largely organised within countries; goods and services only crossed borders in the form of trade, and markets were mostly local. Now **production is spread across countries**: MNCs split production into parts across locations to cut costs, as with a company that designs in one country, assembles in another and sells everywhere.", "MNCs spread their production in several ways: **setting up their own factories**, **buying** local companies, **partnership** (joint production) with local companies, giving **orders to small producers**, whose products they then sell under their own brand name, and **outsourcing**. Big MNCs hold great power over small producers, who must keep prices and quality as dictated.", "**Foreign Direct Investment (FDI):** investment made by MNCs in the country in factories, machines and offices. MNCs invest where the market is large, labour is cheap, infrastructure is good and government policies protect their interest. Investment by MNCs is an important way in which countries are being connected."]),
 ("h2", "Interlinking of Production and Markets"),
 ("ul", ["**Foreign trade** is the main channel connecting countries: goods produced in one country reach markets of other countries, giving consumers more choice and exposing local producers to competition from imports.", "Prices of the same goods in different markets move closer together, and producers in different countries compete."]),
 ("h2", "What Made Globalisation Possible?"),
 ("ol", ["**Technology:** rapid improvement in transportation (containers, cheaper shipping and air cargo) and in **information and communication technology (IT)**, such as telecommunication, computers and the internet. Services like call centres, data entry, accounting and engineering can be done from anywhere (**outsourcing**).", "**Liberalisation of foreign trade and foreign investment policy:** removal of barriers set by the government.", "**Pressure from international organisations:** the World Trade Organisation and the IMF and World Bank pushed developing countries to liberalise."]),
 ("note", "IMPORTANT", "**Trade barriers** are restrictions on trade, such as a **tax on imports** (tariff) or a limit on the number of goods that can be imported (**quota**). Governments can increase or decrease trade barriers. Removing barriers is **liberalisation**."),
 ("ul", ["India put barriers on foreign trade and investment after independence, to protect domestic producers from foreign competition; imports were allowed only for essential items such as machines, fertilisers and petroleum.", "In **1991** India adopted **new economic policy (liberalisation, privatisation and globalisation)**: removal of many barriers; quantitative restrictions on imports were removed by 2001; the government reduced taxes on imports; **Special Economic Zones (SEZs)** were set up with world-class facilities such as electricity, water, roads and tax holidays to attract foreign companies.", "The **World Trade Organisation (WTO)**, established in **1995** at Geneva, is an organisation whose aim is to liberalise international trade; it sets rules for international trade and sees that they are followed. Over 160 countries are members. In practice, developed countries have kept their own barriers, e.g. on agriculture, while asking developing countries to remove theirs."]),
 ("h2", "Impact of Globalisation in India"),
 ("table", ["Group", "Impact"], [["Consumers", "Wider choice of goods, better quality and lower prices, especially for the well-off urban"], ["Large Indian companies", "Gained: invested in modern technology, collaborated with foreign companies; some became MNCs themselves (**Tata Motors**, **Infosys**, **Ranbaxy**, **Asian Paints**, **Sundaram Fasteners**)"], ["Service providers", "IT, BPO and call centres grew; software, accounting and legal services are exported"], ["Small producers and workers", "Many small producers (batteries, capacitors, plastics, toys, vegetable oil) lost out because of competition from cheap imports; workers lost jobs; jobs became more **flexible**, with temporary workers hired and lower wages"]]),
 ("p", "Globalisation has created new opportunities for companies providing services; some producers and workers have not shared the benefits equally."),
 ("h2", "The Struggle for a Fair Globalisation"),
 ("ul", ["Globalisation has benefited well-off consumers and skilled and educated producers, but a large number of small producers and workers have not benefited. **Fair globalisation** would create opportunities for all and ensure that the benefits are shared better.", "The government can ensure that **labour laws** are properly implemented and workers get their rights, support small producers to improve performance, negotiate in the WTO for **fairer rules**, and form alliances with other developing countries.", "Unions, **mass movements and campaigns** in the world have taken up issues about the working conditions and fair prices."]),
 ("h2", "Quick Revision: Likely Exam Questions"),
 ("qa", [
  ("What is an MNC?", "A company owning or controlling production in more than one country."),
  ("What is FDI?", "Investment by MNCs in factories, machines and offices abroad."),
  ("What is liberalisation?", "Removal of government barriers to trade and investment."),
  ("What is a trade barrier?", "Tax or quota on imports."),
  ("What are SEZs?", "Zones with world-class facilities and tax benefits to attract investment."),
  ("What is the WTO?", "Organisation (1995) that sets and enforces rules for international trade."),
  ("Who lost from globalisation?", "Many small producers and workers facing cheap imports."),
 ]),
 ],
 takeaways=["**MNCs** spread production across countries through investment, partnership, outsourcing and orders.", "Globalisation grew with **technology**, **liberalisation** and pressure from international bodies.", "India liberalised in **1991**; **WTO** formed in 1995; **SEZs** attract investment.", "Benefits have been uneven: big firms and services gained, small producers and workers faced pressure.", "A **fair globalisation** needs better rules, labour protection and support for small producers."])
